	screen.Clear()
	e.GameMap.Render(screen)
	for _, ent := range e.Entities {
		if e.GameMap.IsVisible(ent.X, ent.Y) {
			screen.SetContent(ent.X, ent.Y, ent.Char, nil, tcell.StyleDefault.Foreground(ent.Color))
		}
	}
	screen.Show()
}

