package main

import (
	"encoding/gob"
	"os"
)

const saveFile = "savegame.sav"

const saveVersion = 1

type saveData struct {
	Version     int // your turn! write it in SaveAs, check it in LoadGame
	GameMap     *GameMap
	MessageLog  *MessageLog
	PlayerIndex int
}

